import csv
import io


def read_table(path, required, error_cls, parse_row):
    try:
        with open(path, "rb") as f:
            data = f.read()
        text = data.decode("utf-8-sig")
        reader = csv.reader(io.StringIO(text, newline=""))
        header = next(reader, None)
        if not header:
            raise error_cls(f"{path}: missing header")
        names = [h.strip().lower() for h in header]
        seen = set()
        for name in names:
            if name in seen:
                raise error_cls(f"{path}: duplicate column '{name}'")
            seen.add(name)
        for col in required:
            if col not in seen:
                raise error_cls(f"{path}: missing column '{col}'")
        index = {col: names.index(col) for col in required}
        results = []
        for row in reader:
            if not row:
                continue
            if len(row) != len(names):
                raise error_cls(
                    f"{path}:{reader.line_num}: expected {len(names)} fields, got {len(row)}"
                )
            values = {col: row[i].strip() for col, i in index.items()}
            results.append(parse_row(path, reader.line_num, values))
        return results
    except OSError:
        raise error_cls(f"{path}: cannot read file") from None
    except UnicodeDecodeError:
        raise error_cls(f"{path}: not valid UTF-8") from None
    except csv.Error:
        raise error_cls(f"{path}: cannot read file") from None

import pytest

from csvledger.csvio import read_table
from csvledger.errors import RulesFileError, TransactionFileError

REQ = ["date", "description", "amount"]


def parse(path, line, values):
    return (line, values)


def read(p, cls=TransactionFileError, parse_row=parse, required=REQ):
    return read_table(str(p), required, cls, parse_row)


def err(p, cls=TransactionFileError, **kw):
    with pytest.raises(cls) as ei:
        read(p, cls, **kw)
    return ei.value.message


def w(tmp_path, data):
    p = tmp_path / "f.csv"
    p.write_bytes(data)
    return p


def test_basic_and_extra_columns(tmp_path):
    p = w(tmp_path, b"date,description,amount,x\n2026-01-01, a ,1,z\n")
    assert read(p) == [(2, {"date": "2026-01-01", "description": "a", "amount": "1"})]


def test_bom_crlf_blank_lines(tmp_path):
    p = w(tmp_path, b"\xef\xbb\xbfdate,description,amount\r\n\r\n2026-01-01,a,1\r\n\r\n2026-01-02,b,2\r\n")
    r = read(p)
    assert [x[0] for x in r] == [3, 5]
    assert r[1][1]["description"] == "b"


def test_header_only(tmp_path):
    assert read(w(tmp_path, b"date,description,amount\n")) == []


def test_zero_bytes_and_bom_only_and_blank_first_line(tmp_path):
    for data in (b"", b"\xef\xbb\xbf", b"\ndate,description,amount\n"):
        p = w(tmp_path, data)
        assert err(p) == f"{p}: missing header"


def test_duplicate_column(tmp_path):
    p = w(tmp_path, b"date,Amount,description, AMOUNT,date\n")
    assert err(p) == f"{p}: duplicate column 'amount'"


def test_duplicate_beats_missing(tmp_path):
    p = w(tmp_path, b"x,x\n")
    assert err(p) == f"{p}: duplicate column 'x'"


def test_missing_column_first_in_order(tmp_path):
    p = w(tmp_path, b"description\n")
    assert err(p) == f"{p}: missing column 'date'"


def test_field_count_mismatch(tmp_path):
    p = w(tmp_path, b"date,description,amount\n2026-01-01,a\n")
    assert err(p) == f"{p}:2: expected 3 fields, got 2"
    p = w(tmp_path, b"date,description,amount\n2026-01-01,a,1,2\n")
    assert err(p) == f"{p}:2: expected 3 fields, got 4"


def test_field_count_multiline_quoted(tmp_path):
    p = w(tmp_path, b'date,description,amount\n2026-01-01,"a\nb\nc"\n')
    assert err(p) == f"{p}:4: expected 3 fields, got 2"


def test_multiline_quoted_ok(tmp_path):
    p = w(tmp_path, b'date,description,amount\n2026-01-01,"a\nb",1\n')
    r = read(p)
    assert r[0][0] == 3
    assert r[0][1]["description"] == "a\nb"


def test_invalid_utf8(tmp_path):
    p = w(tmp_path, b"date,description,amount\n2026-01-01,\xff,1\n")
    assert err(p) == f"{p}: not valid UTF-8"


def test_missing_file_and_directory(tmp_path):
    p = tmp_path / "nope.csv"
    assert err(p) == f"{p}: cannot read file"
    assert err(tmp_path) == f"{tmp_path}: cannot read file"


def test_column_order_independence(tmp_path):
    p = w(tmp_path, b"amount,date,description\n1,2026-01-01,a\n")
    assert read(p)[0][1] == {"amount": "1", "date": "2026-01-01", "description": "a"}


def test_header_normalization(tmp_path):
    p = w(tmp_path, b" DATE , Description,AMOUNT \n2026-01-01,a,1\n")
    assert read(p)[0][1]["description"] == "a"


def test_error_class_passed_in(tmp_path):
    p = w(tmp_path, b"")
    assert err(p, RulesFileError) == f"{p}: missing header"


def test_parse_row_error_earlier_beats_field_count_later(tmp_path):
    p = w(tmp_path, b"date,description,amount\nbad,a,1\n2026-01-01,a\n")

    def bad(path, line, values):
        raise TransactionFileError(f"{path}:{line}: invalid date '{values['date']}'")

    assert err(p, parse_row=bad) == f"{p}:2: invalid date 'bad'"


def test_decode_error_beats_row_error(tmp_path):
    p = w(tmp_path, b"date,description,amount\nbad,a,1\n2026-01-01,\xff,1\n")

    def bad(path, line, values):
        raise TransactionFileError("row error")

    assert err(p, parse_row=bad) == f"{p}: not valid UTF-8"

