import datetime
import decimal
import re
from dataclasses import dataclass
from decimal import Decimal

from csvledger import csvio
from csvledger.errors import TransactionFileError

_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_AMOUNT_RE = re.compile(r"-?[0-9]+(\.[0-9]+)?")


@dataclass(frozen=True)
class Transaction:
    date: datetime.date
    description: str
    amount: Decimal


def decimal_context(digits):
    return decimal.Context(
        prec=max(50, digits + 30),
        traps=[decimal.Inexact, decimal.Rounded, decimal.InvalidOperation],
    )


def parse_row(path, line, values):
    raw_date = values["date"]
    m = _DATE_RE.fullmatch(raw_date)
    parsed = None
    if m:
        try:
            parsed = datetime.date(int(m[1]), int(m[2]), int(m[3]))
        except ValueError:
            pass
    if parsed is None:
        raise TransactionFileError(f"{path}:{line}: invalid date '{raw_date}'")
    raw_amount = values["amount"]
    if not _AMOUNT_RE.fullmatch(raw_amount):
        raise TransactionFileError(f"{path}:{line}: invalid amount '{raw_amount}'")
    with decimal.localcontext(decimal_context(len(raw_amount))):
        amount = Decimal(raw_amount)
    return Transaction(parsed, values["description"], amount)


def load_transactions(paths):
    rows = []
    for path in paths:
        rows.extend(
            csvio.read_table(
                path, ("date", "description", "amount"), TransactionFileError, parse_row
            )
        )
    return rows


def dedup(rows):
    seen = set()
    kept = []
    for row in rows:
        if row in seen:
            continue
        seen.add(row)
        kept.append(row)
    return kept, len(rows) - len(kept)

