import pytest

from csvledger.errors import RulesFileError
from csvledger.rules import categorize, load_rules

HDR = "category,type,pattern,priority\n"
O1 = (
    HDR
    + "Groceries,contains,market,10\n"
    + "Coffee,regex,^(starbucks|blue bottle),10\n"
    + "Dining,contains,cafe,5\n"
    + "Salary,contains,payroll,0\n"
)


def write(tmp_path, text):
    p = tmp_path / "rules.csv"
    p.write_text(text, encoding="utf-8", newline="")
    return str(p)


def err(tmp_path, text):
    p = write(tmp_path, text)
    with pytest.raises(RulesFileError) as e:
        load_rules(p)
    return e.value.message.replace(p, "rules.csv")


def test_o1(tmp_path):
    rules = load_rules(write(tmp_path, O1))
    assert categorize(rules, "Blue Bottle Cafe") == "Coffee"
    assert categorize(rules, "STARBUCKS #12") == "Coffee"
    assert categorize(rules, "Corner Market") == "Groceries"
    assert categorize(rules, "ACME PAYROLL") == "Salary"
