import decimal
import json
from decimal import Decimal

_CENT = Decimal("0.01")


def format_money(value):
    ctx = decimal.Context(
        prec=len(value.as_tuple().digits) + abs(value.as_tuple().exponent) + 10,
        rounding=decimal.ROUND_HALF_UP,
        traps=[decimal.InvalidOperation],
    )
    q = value.quantize(_CENT, context=ctx)
    if q == 0:
        return "0.00"
    return format(q, "f")


def _table(headers, aligns, rows):
    widths = [
        max(len(h), *(len(r[i]) for r in rows)) if rows else len(h)
        for i, h in enumerate(headers)
    ]

    def line(cells):
        parts = [
            c.rjust(w) if a == "R" else c.ljust(w)
            for c, w, a in zip(cells, widths, aligns)
        ]
        return "  ".join(parts).rstrip() + "\n"

    out = [line(headers), line(["-" * w for w in widths])]
    out.extend(line(r) for r in rows)
    return "".join(out)


def _json(obj):
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def _money_fields(e):
    return {
        "count": e.count,
        "income": format_money(e.income),
        "expenses": format_money(e.expenses),
        "net": format_money(e.net),
    }


def render_report(groups, fmt):
    if fmt == "json":
        months = []
        for g in groups:
            d = {"month": g.month, **_money_fields(g)}
            d["categories"] = [
                {"category": c.category, **_money_fields(c)} for c in g.categories
            ]
            months.append(d)
        return _json({"months": months})
    rows = [
        [g.month, c.category, str(c.count), format_money(c.income),
         format_money(c.expenses), format_money(c.net)]
        for g in groups
        for c in g.categories
    ]
    return _table(
        ["MONTH", "CATEGORY", "COUNT", "INCOME", "EXPENSES", "NET"],
        "LLRRRR",
